  "args": {
    "old_content": "module TopModule (
    input  logic clk,
    input  logic a,
    output logic q
);

    // Initialize to a known value to avoid X before the first posedge.
    initial q = 1'b0;

    // Sequential logic: update q on the positive edge of clk.
    always @(posedge clk) begin
        q <= ~a;
    end

endmodule
